solution.solution.cpp:
class BankAccount
{
public:
    bool deposit(long long cents)
    {
        if (cents <= 0)
        {
            return false;
        }
        m_balance += cents;
        ++m_transactions;
        return true;
    }

    bool withdraw(long long cents)
    {
        if (cents <= 0 || cents > m_balance)
        {
            return false;
        }
        m_balance -= cents;
        ++m_transactions;
        return true;
    }

    long long balance() const { return m_balance; }
    int transactions() const { return m_transactions; }

private:
    long long m_balance{ 0 };
    int m_transactions{ 0 };
};

unitTests:
TEST("starts empty") { const BankAccount a{}; CHECK_EQ(a.balance(), 0); CHECK_EQ(a.transactions(), 0); }
TEST("deposit and withdraw") { BankAccount a{}; CHECK(a.deposit(10000)); CHECK(a.withdraw(2550)); CHECK_EQ(a.balance(), 7450); CHECK_EQ(a.transactions(), 2); }
TEST("cannot overdraw") { BankAccount a{}; a.deposit(500); CHECK(!a.withdraw(501)); CHECK_EQ(a.balance(), 500); CHECK(a.withdraw(500)); CHECK_EQ(a.balance(), 0); }
TEST("silly amounts are refused") { BankAccount a{}; CHECK(!a.deposit(0)); CHECK(!a.deposit(-100)); a.deposit(100); CHECK(!a.withdraw(0)); CHECK(!a.withdraw(-5)); CHECK_EQ(a.balance(), 100); }
TEST("only successes are counted") { BankAccount a{}; a.deposit(-1); a.withdraw(10); a.deposit(50); CHECK_EQ(a.transactions(), 1); }

